arguments.reputation_value:
{%- set ti_conf = (
    (vars.steps.Get_Threat_Intel_Reputation | default({}))
    .get('data', {})
    .get('confidence', '')
) | trim -%}

{%- set rep_conf = (
    (vars.steps.Get_Reputation | default({}))
    .get('data', {})
    .get('data', [])
    | first
    | default({})
).get('values', {})
 .get('threatinfo', {})
 .get('confidence', '') | trim -%}

{%- set conf = ti_conf if ti_conf | lower in ['high','medium','low']
    else rep_conf if rep_conf | lower in ['high','medium','low']
    else '' -%}

{{- conf | lower if conf else '' -}}
